/**
 * The kOS database: every structure, suffix, builtin function and bound
 * variable of one kOS version, with its documentation.
 *
 * It is generated by tools/kos-db from the kOS sources (C# for the
 * model, Sphinx documentation for the text) merged with the previous
 * database and data/overrides.json, and loaded at startup to build the
 * type checker's types.
 *
 * Type expressions are strings in kOS type names: `Scalar`,
 * `List<Part>`, `Lexicon<String, Structure>`, `String | Path`. `None` is
 * the type of nothing (a suffix or function used as a statement).
 */
export interface KosDatabase {
  /** kOS version the database describes, e.g. `1.6.0.1` */
  kos: string;

  /** base of documentation urls, e.g. `https://ksp-kos.github.io/KOS/` */
  docsBase: string;

  /** structures by kOS type name (`Vessel`, `Stage`, `List`) */
  structures: Record<string, StructureEntry>;

  /** builtin functions, by name in camel case (`clearVecDraws`) */
  functions: Record<string, FunctionEntry>;

  /** bound variables, by name in camel case (`ship`, `missionTime`) */
  variables: Record<string, VariableEntry>;
}

/**
 * Documentation of an entry
 */
export interface Documented {
  /** documentation in Markdown */
  doc?: string;

  /** documentation page, relative to docsBase, with its anchor */
  url?: string;
}

/**
 * A structure (a kOS type)
 */
export interface StructureEntry extends Documented {
  /** the structure it inherits suffixes from */
  inherits?: string;

  /** type parameters, for the generic collections (`List<T>`) */
  parameters?: string[];

  /**
   * suffixes by name in camel case, which gives their word boundaries
   * (`stageDeltaV`); lookup is case-insensitive
   */
  suffixes: Record<string, SuffixEntry>;

  /**
   * whether suffixes can be added at runtime (part module fields, lexicon
   * keys, addons): unknown suffixes are then not reported
   */
  dynamic?: boolean;
}

/**
 * How a suffix is used
 * - `get`: read only value
 * - `getset`: value that can be set
 * - `set`: value that can only be set
 * - `call`: method, called with arguments (or none)
 */
export type SuffixAccess = 'get' | 'getset' | 'set' | 'call';

/**
 * A suffix of a structure
 */
export interface SuffixEntry extends Documented {
  access: SuffixAccess;

  /** type of the value, or of the result for a call */
  type: string;

  /** parameters, for a call */
  params?: ParameterEntry[];

  /** other names of the same suffix */
  aliases?: string[];

  /** units of the value, e.g. `m/s` */
  units?: string;
}

/**
 * A parameter of a suffix or function
 */
export interface ParameterEntry extends Documented {
  /** name in the documentation */
  name?: string;

  type: string;

  /** can be omitted (and the following parameters with it) */
  optional?: boolean;

  /** stands for any number of arguments of its type */
  variadic?: boolean;
}

/**
 * A builtin function
 */
export interface FunctionEntry extends Documented {
  returns: string;
  params: ParameterEntry[];

  /** other names of the same function */
  aliases?: string[];
}

/**
 * A bound variable (`ship`, `time`, `throttle`...)
 */
export interface VariableEntry extends Documented {
  type: string;

  /** `getset` for variables that can be set (`set target to ...`) */
  access: 'get' | 'getset';

  /** units of the value, e.g. `m` */
  units?: string;

  /**
   * whether kOS reads it continuously when it is locked (`lock throttle
   * to ...`): `throttle`, `steering`, `wheelThrottle`, `wheelSteering`
   */
  lock?: boolean;
}
